export type TitleId = (typeof TITLES)[number]["id"];

export const TITLE_IDS: readonly TitleId[] = TITLES.map((t) => t.id);

const BY_ID = new Map<string, TitleDef>(TITLES.map((t) => [t.id, t]));

export function getTitle(id: string | null | undefined): TitleDef | undefined {
  return id ? BY_ID.get(id) : undefined;
}

/** What `/api/titles` answers (00152 titles_json, 00156): the title worn,
 * every one earned, the numbers progress is shown on, how many herzies hold
 * each title out of how many there are in all, and the ones this very
 * request granted. */
export interface TitlesState {
  worn: TitleId | null;
  earned: EarnedTitle[];
  metrics: TitleMetrics;
  holders: Partial<Record<TitleId, number>>;
  /** Herzies in all: what `holders` are a share of. */
  herzies: number;
  granted: TitleId[];
}

export function isTitleId(id: unknown): id is TitleId {
  return typeof id === "string" && BY_ID.has(id);
}

/** A herzie's earned title, as `/api/titles` lists it. */
export interface EarnedTitle {
  id: TitleId;
  /** ISO time it was first earned. */
  earnedAt: string;
  /** Times earned: more than 1 only for repeatable feats (Chart Topper). */
  count: number;
  /** Not looked at in the Titles tab yet: "NEW". */
  fresh: boolean;
}

/** How far a herzie is towards a title, 0–1, or null when it has no
 * progress to show (a judged feat, or a retired title). */
export function titleProgress(
  def: TitleDef,
  metrics: TitleMetrics | null | undefined,
): number | null {
  if (!def.metric || !def.goal || def.retired || !metrics) return null;
  return Math.max(0, Math.min(1, (metrics[def.metric] ?? 0) / def.goal));
}

/** What the progress bar says: "38 / 50 h", "Floor 12 / 20", "3 / 10". */
export function titleProgressLabel(
  def: TitleDef,
  metrics: TitleMetrics | null | undefined,
): string | null {
  if (!def.metric || !def.goal || def.retired || !metrics) return null;
  const have = Math.min(metrics[def.metric] ?? 0, def.goal);
  if (def.metric === "minutes") {
    return `${Math.floor(have / 60).toLocaleString("en-US")} / ${(def.goal / 60).toLocaleString("en-US")} h`;
  }
  if (def.metric === "towerFloor") return `Floor ${have} / ${def.goal}`;
  if (def.metric === "level") return `Level ${have} / ${def.goal}`;
  if (def.metric === "streak") return `${have} / ${def.goal} days`;
  return `${have.toLocaleString("en-US")} / ${def.goal.toLocaleString("en-US")}`;
}

/** The ladder titles `metrics` has reached: what refresh_titles would grant
 * (judged feats aside). For the app to tell which are within reach. */
export function titlesReached(metrics: TitleMetrics): TitleId[] {
  return TITLES.filter(
    (t: TitleDef) =>
      !t.retired && t.metric && t.goal && metrics[t.metric] >= t.goal,
  ).map((t) => t.id);
}

/** The metrics a sync moves (listening, XP, the streak), as they stand on a
 * herzie, counted the way `title_metrics` (00152) counts them. */
export function syncTitleMetrics(herzie: {
  totalMinutesListened: number;
  level: number;
  streakDays: number;
  genreMinutes: Record<string, number>;
}): Pick<TitleMetrics, "minutes" | "level" | "streak" | "genres"> {
  return {
    minutes: Math.floor(Number(herzie.totalMinutesListened) || 0),
    level: herzie.level,
    streak: herzie.streakDays,
    genres: GENRES.filter((g) => (herzie.genreMinutes[g] ?? 0) >= 60).length,
  };
}

/** Whether going from `before` to `after` reaches a title's goal, on the
 * metrics both name. The sync's cheap check, so it only asks the database to
 * grant (refresh_titles) when something can have been earned. */
export function titleGoalReached(
  before: Partial<TitleMetrics>,
  after: Partial<TitleMetrics>,
): boolean {
  return TITLES.some((t: TitleDef) => {
    if (t.retired || !t.metric || !t.goal) return false;
    const was = before[t.metric];
    const now = after[t.metric];
    return (
      was !== undefined && now !== undefined && was < t.goal && now >= t.goal
    );
  });
}

/** Title ids in the catalog's order, unknown ones left out: how a list of
 * them is shown (a toast of several, the earned list). */
export function inCatalogOrder(ids: readonly unknown[]): TitleId[] {
  const want = new Set(ids);
  return TITLE_IDS.filter((id) => want.has(id));
}
